<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
const props=defineProps<{request:(path:string,method:string,body?:unknown)=>Promise<unknown>}>();
type Status={policy:{limitBytes:number;autoCleanup:boolean};usedBytes:number;breakdown?:Record<string,number>;messages:number;disk:{freeBytes:number;totalBytes:number}|null};
const data=ref<Status>(),limit=ref(0),busy=ref(false),error=ref(''),note=ref('');let timer:ReturnType<typeof setInterval>|undefined;
const gib=1024**3;
const categories=[['messages','Сообщения'],['photos','Фото'],['video','Видео'],['audio','Аудио'],['files','Файлы'],['other','Профили и настройки']];
const maxLimit=computed(()=>data.value?.disk?Math.floor(data.value.disk.totalBytes/gib*1000)/1000:undefined);
function size(n:number){const unit=n>=1024**3?3:n>=1024**2?2:n>=1024?1:0;return new Intl.NumberFormat('ru',{maximumFractionDigits:1}).format(n/1024**unit)+' '+['Б','КБ','МБ','ГБ'][unit];}
async function load(initial=false){try{data.value=await props.request('/api/storage','GET') as Status;if(initial){limit.value=Math.min(data.value.policy.limitBytes/gib,maxLimit.value??Infinity);}}catch(e){error.value=(e as Error).message;}}
async function save(){busy.value=true;error.value='';note.value='';try{data.value=await props.request('/api/storage','PATCH',{limitBytes:Math.round(limit.value*gib)}) as Status;note.value='Настройки сохранены.';}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(()=>{void load(true);timer=setInterval(()=>void load(),15000)});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><section class="storage-settings"><h3>Хранилище сервера</h3><p class="field-help">Лимит для сообщений, вложений, аватаров и профилей этого сервера. Резервные копии и другие приложения в него не входят.</p><div v-if="data" class="storage-meter"><div><strong>{{size(data.usedBytes)}}</strong><span>из {{size(data.policy.limitBytes)}}</span></div><progress :value="data.usedBytes" :max="data.policy.limitBytes" aria-label="Занятое место"/><small>Сообщений: {{data.messages}}</small><dl v-if="data.breakdown" class="storage-breakdown"><div v-for="[key,label] in categories" :key="key"><dt>{{label}}</dt><dd>{{size(data.breakdown[key!]||0)}}</dd></div></dl><p v-if="data.disk">Свободно на разделе хранилища: {{size(data.disk.freeBytes)}} из {{size(data.disk.totalBytes)}}</p><p v-else>Показатели диска недоступны.</p><p v-if="data.disk">Это раздел, доступный серверу Nimbo; он может занимать только часть диска VPS. Лимит хранения задаётся отдельно.</p></div><form @submit.prevent="save"><label>Лимит хранения, ГБ<input type="number" :min="8/1024" :max="maxLimit" step="any" v-model.number="limit" required :disabled="busy"></label><p v-if="maxLimit" class="field-help storage-maximum">Максимум — {{maxLimit.toLocaleString('ru')}} ГБ, объём доступного раздела.</p><p class="field-help">При заполнении 90% лимита удаляются самые старые сообщения в чатах. Удаление необратимо. Если уменьшить лимит и сохранить, лишняя история удалится сразу. Профили, аватары и каналы сохраняются.</p><button class="primary" :disabled="busy">Сохранить настройки</button></form><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="note" class="field-help" role="status">{{note}}</p></section></template>
<style scoped>
.storage-breakdown{margin:18px 0 0;font-size:13px}.storage-breakdown>div{display:flex;justify-content:space-between;gap:16px;padding:7px 0;border-bottom:1px solid #ffffff08}.storage-breakdown dt{color:#aaa}.storage-breakdown dd{margin:0;font-variant-numeric:tabular-nums}.storage-maximum{margin-top:-8px}.storage-meter{padding:20px;background:#171717;border-radius:14px;margin:20px 0}.storage-meter>div{display:flex;gap:8px;align-items:baseline}.storage-meter strong{font-size:20px}.storage-meter span,.storage-meter small,.storage-meter p{font-size:12px;color:#999}.storage-meter progress{display:block;width:100%;height:8px;appearance:none;border:0;margin:16px 0 10px;border-radius:4px;overflow:hidden}.storage-meter progress::-webkit-progress-bar{background:#333}.storage-meter progress::-webkit-progress-value{background:#66aaf0}.storage-meter progress::-moz-progress-bar{background:#66aaf0}.storage-meter p{margin-top:14px}.storage-settings input[type=number]{max-width:220px;display:block}
</style>
